------------------
---- MONITORS ----
------------------

-- See https://wiki.hypr.land/configuring/core/monitors/
-- Laptop panel: 2880x1800 OLED at 2x
hl.monitor({
    output   = "eDP-1",
    mode     = "preferred",
    position = "0x0",
    scale    = 2,
})

-- Anything plugged in (monitor, projector): extend to the right by default.
-- Choose Extend / Mirror / External only / Laptop only in the dashboard (Super+A);
-- the F8 display key cycles through them.
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto-right",
    scale    = "auto",
})


---------------------
---- MY PROGRAMS ----
---------------------

-- Set programs that you use
local terminal    = "kitty"
local fileManager = "dolphin"
local menu = "qs ipc call panels toggle launcher"   -- Nixie launcher (apps, calculator, > commands)


-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/configuring/core/autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
-- hl.on("hyprland.start", function ()
--   hl.exec_cmd(terminal)
--   hl.exec_cmd("nm-applet")
--   hl.exec_cmd("waybar & hyprpaper & firefox")
-- end)

hl.on("hyprland.start", function ()
    -- Restore the saved software brightness + warm tint
    hl.exec_cmd("~/.local/bin/brightness apply")
    -- Idle: lock + screen off 5 min, hibernate after 30 min on battery at night (hypridle.conf)
    hl.exec_cmd("hypridle")
    -- Password prompts for privileged actions: the Nixie shell is the polkit agent (PolkitDialog.qml)
    -- hl.exec_cmd("systemctl --user start hyprpolkitagent")   -- replaced by the shell
    -- Nixie shell: bar, attention rail, notifications (~/.config/quickshell)
    hl.exec_cmd("qs -d -n")
    -- Clipboard history for the Super+V picker
    hl.exec_cmd("wl-paste --watch cliphist store")
    -- Chinese/Japanese input (Alt + right Shift switches, as on the arch machine)
    hl.exec_cmd("~/.local/bin/start-fcitx")
end)


