-- Refer to https://wiki.hypr.land/configuring/core/config-options/
hl.config({
    general = {
        gaps_in  = 4,   -- 8px between windows
        gaps_out = { top = 4, right = 8, bottom = 8, left = 8 },   -- 4px under the bar, 8px elsewhere

        border_size = 2,

        col = {
            active_border   = "rgba(ffac32cc)",   -- Nixie amber: the focused window
            inactive_border = "rgba(2e2c2aff)",   -- frame hairline grey
        },

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,

        -- Please see https://wiki.hypr.land/configuring/extra/tearing/ before you turn this on
        allow_tearing = false,

        layout = "dwindle",
    },

    -- Software cursor so the screen shader also tints/dims the pointer
    -- (hardware cursor planes bypass screen_shader).
    cursor = {
        no_hardware_cursors = 1,
    },

    decoration = {
        -- Warm + dim filter (temporary; replace with hyprsunset once installed)
        screen_shader  = "/home/brine/.config/hypr/shaders/warm-dim.frag",

        rounding       = 12,  -- frame inner radius (20) minus gap (8)
        rounding_power = 2,

        -- Change transparency of focused and unfocused windows
        active_opacity   = 1.0,
        inactive_opacity = 1.0,

        shadow = {
            enabled      = true,
            range        = 4,
            render_power = 3,
            color        = 0xee1a1a1a,
        },

        blur = {
            enabled   = true,
            size      = 2,      -- frosted glass for the Nixie shell + translucent windows
            passes    = 1,
            vibrancy  = 0.1696,
        },
    },

    animations = {
        enabled = true,
    },
})

-- Default curves and animations, see https://wiki.hypr.land/configuring/core/animations/
hl.curve("easeOutQuint",   { type = "bezier", points = { {0.23, 1},    {0.32, 1}    } })
