---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Example binds, see https://wiki.hypr.land/configuring/core/binds/ for more
hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd(terminal))
local closeWindowBind = hl.bind(mainMod .. " + C", hl.dsp.window.close())
-- closeWindowBind:set_enabled(false)
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'"))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + V", hl.dsp.exec_cmd("qs ipc call panels toggle clipboard"))
hl.bind(mainMod .. " + SHIFT + V", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + SHIFT + P", hl.dsp.window.pseudo())
-- Displays: extend / mirror / external only / laptop only (like Win+P)
hl.bind("XF86Display", hl.dsp.exec_cmd("~/.local/bin/display-mode next"))
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))    -- dwindle only

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    -- If a scratchpad (e.g. Discord on Super+D) is open, close it first so you
    -- actually land on workspace i instead of keeping the scratchpad on top.
    hl.bind(mainMod .. " + " .. key, function ()
        local sp = hl.get_active_special_workspace()
        if sp ~= nil then
            hl.dispatch(hl.dsp.workspace.toggle_special((sp.name:gsub("^special:", ""))))
        end
        hl.dispatch(hl.dsp.focus({ workspace = i }))
    end)
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end


-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })
hl.bind(mainMod .. " + ALT + mouse:272", hl.dsp.window.resize(), { mouse = true })   -- Super+Alt + press and drag: resize (one-finger touchpad press works)

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, repeating = true })
-- Brightness keys: ~/.local/bin/brightness sets the panel backlight in fine steps
-- (2%, or 1% below 20%) and keeps the bar/OSD level in sync.
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("~/.local/bin/brightness up"),                    { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("~/.local/bin/brightness down"),                  { locked = true, repeating = true })

-- Caps Lock (keycode 66, its normal function disabled above): English <-> 注音/last input method
hl.bind("code:66", hl.dsp.exec_cmd("fcitx5-remote -t"))

-- Power key: wakes the display if off, otherwise opens the session menu
-- (needs logind HandlePowerKey=ignore: install/power/90-power-key-menu.conf)
hl.bind("XF86PowerOff", hl.dsp.exec_cmd("~/.local/bin/power-button"), { locked = true })

-- Dock: Super+D slides it in/out (or rest the pointer on the right edge ~2 s)
-- Super+H: the hidden workspace (music, things to keep running out of sight): show / hide it.
-- Super+Shift+H: send the focused window there (it disappears), or, when it's
-- already in there, bring it back to the workspace underneath.
hl.bind(mainMod .. " + H", hl.dsp.workspace.toggle_special("hidden"))
hl.bind(mainMod .. " + SHIFT + H", function ()
    local w = hl.get_active_window()
    if w == nil then return end
    if w.workspace ~= nil and w.workspace.name == "special:hidden" then
        local ws = hl.get_active_workspace()            -- the regular workspace under it
        hl.dispatch(hl.dsp.window.move({ workspace = ws.id }))
        local sp = hl.get_active_special_workspace()
        if sp ~= nil and sp.name == "special:hidden" then hl.dispatch(hl.dsp.workspace.toggle_special("hidden")) end
    else
        hl.dispatch(hl.dsp.window.move({ workspace = "special:hidden" }))
        local sp = hl.get_active_special_workspace()     -- moving shows it; hide it again
        if sp ~= nil and sp.name == "special:hidden" then hl.dispatch(hl.dsp.workspace.toggle_special("hidden")) end
    end
end)

-- Super+D: Discord scratchpad (starts Discord if needed); Super+Shift+D pins the dock
hl.bind(mainMod .. " + D", hl.dsp.exec_cmd("~/.local/bin/scratch discord '^discord$' discord"))
hl.bind(mainMod .. " + SHIFT + D", hl.dsp.exec_cmd("qs ipc call dock toggle"))
hl.bind(mainMod .. " + A", hl.dsp.exec_cmd("qs ipc call panels toggle dashboard"))

-- Notifications: Super+N centre, Super+Shift+N focus mode (only "needs you" gets through)
hl.bind(mainMod .. " + N", hl.dsp.exec_cmd("qs ipc call notifs toggle"))
hl.bind(mainMod .. " + SHIFT + N", hl.dsp.exec_cmd("qs ipc call notifs focus"))

-- Screenshots: saved to ~/Pictures/Screenshots and copied to the clipboard
-- Print: drag a region on a frozen frame (shot: no mouse pointer), saved + copied. Esc cancels.
hl.bind("Print",               hl.dsp.exec_cmd("~/.local/bin/shot region"))
hl.bind("SHIFT + Print",       hl.dsp.exec_cmd("~/.local/bin/shot window"))
hl.bind(mainMod .. " + Print", hl.dsp.exec_cmd("~/.local/bin/shot output"))

-- Lock now (hyprlock: password or fingerprint)
hl.bind(mainMod .. " + Delete", hl.dsp.exec_cmd("loginctl lock-session"))   -- lock (away from home row on purpose)

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })


--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------

-- See https://wiki.hypr.land/configuring/core/rules/

-- Example window rules that are useful

-- Workspaces 1-5 live on the laptop panel; 6-10 on an extended external screen when
-- one is plugged in, else on the panel too (~/.local/bin/ws-layout moves them, run
-- now and whenever a screen comes or goes). The "agent" workspace belongs to an
-- invisible headless screen (~/.local/bin/agent-screen) that Claude uses to open and
-- screenshot windows without touching your screen or focus.
for i = 1, 10 do
    hl.workspace_rule({ workspace = tostring(i), monitor = "eDP-1" })
end
hl.on("hyprland.start",  function() hl.exec_cmd("~/.local/bin/ws-layout") end)
hl.on("config.reloaded", function() hl.exec_cmd("~/.local/bin/ws-layout") end)
hl.on("monitor.added",   function() hl.exec_cmd("sleep 1; ~/.local/bin/ws-layout") end)
hl.on("monitor.removed", function() hl.exec_cmd("sleep 1; ~/.local/bin/ws-layout") end)
hl.workspace_rule({ workspace = "name:agent", monitor = "AGENT", default = true })

-- Named scratchpads: apps that live in their own special workspace.
hl.window_rule({
    name  = "scratch-discord",
    match = { class = "^discord$" },
    workspace = "special:discord silent",
})

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- Layer rules also return a handle.
-- Nixie shell (Quickshell): frosted glass behind the bar, rail, popups and centre.
hl.layer_rule({
    name  = "nixie-shell-blur",
    match = { namespace = "^nixie-(frame|popups|centre)$" },
    blur = true,
    ignore_alpha = 0.2,   -- blur still applies to the 35% notification centre
})

-- slurp's selection layer and hyprpicker's freeze layer must appear/vanish instantly,
-- otherwise the fading selection border lands in the screenshot.
hl.layer_rule({
    name  = "no-anim-screenshot",
    match = { namespace = "^(selection|hyprpicker)$" },
    no_anim = true,
})

-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- KDE copy/move progress (KIO's job window; without Plasma there's no notification
-- for it). It popped up over the "File Already Exists" prompt and took the focus:
-- keep it out of the way in the bottom-right corner and don't focus it.
-- Titles from KJobWidgets: "Progress Dialog", then "40% of 1 file" / "40% of 3.2 GB".
hl.window_rule({
    name  = "kio-progress-corner",
    match = { class = "^org\\.kde\\.", title = "^(Progress Dialog|[0-9]+% of .*)$" },

    float            = true,
    no_initial_focus = true,
    move             = "monitor_w-window_w-24 monitor_h-window_h-24",
})

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})
